const physicalWhyHow: Record<string, string> = {
  "earths-rotation": "Earth spins because angular momentum from the rotating solar nebula was retained as the forming planet contracted. That spin gives the planet a rotating reference frame, producing the day-night cycle, longitude-based time differences and Coriolis deflection.",
  "earths-revolution": "Earth remains in orbit because the Sun's gravitational attraction continually bends its forward inertial motion into a curved path. The orbital plane and Earth's approximately 23.5° axial tilt create changing solar geometry; axial parallelism changes solar declination and the angle and duration of insolation by latitude, producing the seasonal cycle.",
  "latitude-and-longitude": "A spherical Earth requires angular coordinates to identify position consistently. Latitude is tied to the Equator and the changing angle of solar incidence, while longitude is tied to Earth's rotation and therefore provides the basis for local-time differences.",
  seasons: "Seasons occur because Earth's axis is tilted about 23.5° and maintains its orientation while Earth revolves around the Sun. The tilt changes both solar altitude and daylight duration, so each hemisphere receives different insolation through the year.",
  "earths-interior": "Earth differentiated early in its history because gravity caused dense iron and nickel to sink while lighter silicate material rose. Continuing internal heat and pressure maintain mechanically distinct layers, whose boundaries are inferred from changes in seismic-wave behaviour.",
  "plate-tectonics": "Plate motion is driven by the thermal and gravitational energy of the Earth system: mantle convection contributes, elevated ridges encourage gravitational sliding, and dense subducting slabs pull attached lithosphere downward. These forces create relative motion between rigid plates.",
  earthquakes: "Earthquakes occur when tectonic stress overcomes frictional resistance on a fault. Elastic strain accumulates during locked motion, rupture releases that strain suddenly, and the resulting seismic waves transmit energy through the crust and across the surface.",
};

const physicalMechanisms: Record<string, string> = {
  "earths-rotation": "First, Earth turns around an imaginary axis through the poles. Next, all points share angular velocity but have different distances from the axis. Finally, the resulting rotational frame produces day and night, local-time differences and apparent deflection of moving air and water.",
  "earths-revolution": "1. Earth moves around the Sun along an elliptical orbit. 2. Its axis remains tilted about 23.5° from the perpendicular to the orbital plane. 3. At different orbital positions, different hemispheres tilt toward or away from the Sun. 4. Solar declination shifts between 23.5°N and 23.5°S. 5. Day length and solar altitude change with latitude. 6. These changes produce the seasonal pattern.",
  "latitude-and-longitude": "First, latitude is measured north or south from the Equator along a meridian. Next, longitude is measured east or west from the Prime Meridian along an arc. Their intersection gives a coordinate, while the longitude difference is converted into local-time difference as Earth rotates.",
  seasons: "First, Earth's tilted axis maintains near-parallel orientation during revolution. Next, the subsolar point migrates between the Tropic of Cancer and Tropic of Capricorn. Then solar altitude and day length change by latitude, producing solstices, equinoxes and opposite hemispheric seasons.",
  "earths-interior": "Seismic energy travels outward from an earthquake as P and S waves. At each internal boundary, changes in density and material state alter speed, refraction and transmission. Scientists map these arrivals and shadow zones to infer the crust, mantle, liquid outer core and solid inner core.",
  "plate-tectonics": "At divergent boundaries, mantle material rises and cools into new crust. At convergent boundaries, dense oceanic lithosphere may subduct or continents may collide and thicken crust. At transform boundaries, plates slide laterally and accumulated strain is released as earthquakes.",
  earthquakes: "First, stress deforms rocks around a locked or slipping fault. When resistance is exceeded, rupture starts at the focus and propagates. P, S and surface waves then travel outward; shaking, rupture, liquefaction and secondary hazards vary with distance and ground conditions.",
};

const makeTopic = (seed: TopicSeed): GeographyTopic => {
  const details = { ...topicProfiles[seed.slug], ...physicalDeepProfiles[seed.slug] } as TopicProfile;
  if (!details) throw new Error(`Missing topic content for ${seed.slug}`);
  const sections: TopicSections = {
    overview: seed.shortDescription,
    englishSummary: details.definition,
    coreConcept: details.definition,
    whyHow: physicalWhyHow[seed.slug] ?? `${details.definition} The governing relationship is: ${details.mechanism}`,
    mechanism: physicalMechanisms[seed.slug] ?? details.mechanism,
    keyFacts: details.facts,
    causesComponents: details.causes ?? [`Key components: ${details.terms.slice(0, 3).join(", ")}.`, details.mechanism],
    effectsSignificance: details.effects ?? details.facts.slice(1).concat([`Application: ${details.example}`]),
    geographyConnection: `${details.example} This illustrates how ${seed.title.toLowerCase()} varies by location, scale or environmental context.`,
    bangladeshConnection: details.bangladesh,
    bcsPreli: details.facts,
    writtenPoints: details.written ?? [details.definition, `${details.mechanism} Use ${details.example.toLowerCase()} as a named application in a comparative answer.`],
    misconceptions: details.traps,
    mcqPractice: details.mcqs ?? [1, 2, 3, 4, 5].map((number) => { const answer = details.facts[(number - 1) % details.facts.length]; const term = details.terms[(number - 1) % details.terms.length]; return { question: `${seed.title}: which statement correctly applies ${term} to this topic?`, options: [answer, details.traps[(number - 1) % details.traps.length], `It has no relationship to ${term}.`, "It is defined only by a political boundary."], answer, explanation: `${details.definition} ${details.mechanism}`, shortcutOrTrap: details.traps[(number - 1) % details.traps.length] }; }),
    geographyLink: `Geography turns ${seed.title} from an isolated fact into a spatial question: where does it occur, why there, and with what consequences?`,
    quickRevision: [seed.title, ...details.facts.slice(0, 2), details.terms.slice(0, 2).join(" / "), "Definition → process → spatial example"],
  };
  return { ...seed, terminology: seed.terminology ?? details.terms, establishedFigures: seed.establishedFigures ?? details.facts.filter((fact) => /\d|°|%|\b(19|20)\d{2}\b/.test(fact)), caseStudies: seed.caseStudies ?? [details.example], sections: { ...sections, ...seed.sections } };
};

const topic = (category: string, title: string, slug: string, description: string, difficulty: Difficulty = "Foundation", examRelevance = "High", sections?: Partial<TopicSections>): GeographyTopic => makeTopic({ slug, title, shortDescription: description, category, difficulty, examRelevance, tags: [category.toLowerCase(), "BCS"], sections });
const category = (number: string, slug: string, title: string, eyebrow: string, description: string, topics: GeographyTopic[]): GeographyCategory => ({ number, slug, title, eyebrow, description, topics });

